from pathlib import Path
import json,hashlib
p=Path(__file__).resolve().parent
r=json.loads((p/'timings.json').read_text())[1]['results'];rot=json.loads((p/'rotating-timings.json').read_text())[1]['results'];gr=json.loads((p/'group-profile-timings.json').read_text())[1]['results']
validation=json.loads((p/'validation.json').read_text());stress=json.loads((p/'stress.json').read_text());tr=json.loads((p/'trace-verification.json').read_text());res=json.loads((p/'resources.json').read_text())
assert len(validation)==64 and stress['passed'] and [x['count'] for x in tr]==[17,3,1]
assert all(v['health'] for v in r.values()) and all(v['health'] for v in rot.values()) and all(v['health'] for v in gr.values())
assert all(v['spills']==0 for v in res.values())
lines=['# mHC through attention reduction: Flash C1','','Implemented as `full_prefix`, one kernel launch with 256 CTAs. The complete measured scope includes mHC learned projection and Sinkhorn, stream mixing, input RMSNorm/quantization, QA/KV projections and split-K reduction, weighted RMSNorm, latent quantization, QB projection, Q RMSNorm, Q/KV RoPE, persistent cache write, split-KV attention, and final attention reduction. All cases use split-KV 4.','','The unfused control is a new 17-launch WMMA/TDM control using the same arithmetic and tiling, not the historical vector prototype and not native ATOM/AITER serving. The three-region arm launches mHC, QKV, and attention separately. All learned projections use WMMA; TDM tiled loads and QB/cache L2 prefetch remain enabled.','','## Whole prefix, second round','','GPU-event elapsed time per complete prefix, 128 calls per captured graph, 5 warmups, 40 alternating-order samples, median. The first round is retained but ignored. Includes device gaps within the graph.','','| Context / weights | Unfused, 17 launches (us) | Three regions, 3 launches (us) | Fully fused, 1 launch (us) |','|---|---:|---:|---:|']
for t in [128,1024]:
 vals=[r[f't{t}_{m}']['median_us'] for m in ['unfused','three_regions','fused']]
 lines.append(f'| {t} tokens, reused | '+ ' | '.join(f'{v:.3f}' for v in vals)+' |')
lines.append('| 128 tokens, 16 rotating copies | '+' | '.join(f"{rot[m]['median_us']:.3f}" for m in ['unfused','three_regions','fused'])+' |')
lines+=['','Rotating copies include QA/KV, QB, and mHC projection weights (632 MiB total); identical values at different addresses, not actual different model layers. Scale and norm arrays and the 128-token cache remain shared/reused.','','Single-launch fusion reduces the reused 128-token measurement by 2.9%, is approximately tied/slightly slower with rotating weights, and is slower at 1024 tokens. This is not a consistent whole-prefix speedup. The three-region arm remains competitive. No serving throughput or model-quality claim.','','## Group table','','The first three rows are newly measured at 128 tokens, split-KV 4. These are second-round profiler sums of kernel GPU durations (median of 30 one-invocation graph replays), matching the earlier group-table convention. They exclude inter-kernel gaps and use different replay/cache conditions than the batched GPU-event prefix measurements above; do not add them to predict prefix latency. Raw batched per-group event measurements are also retained in timings.json.','','| Unfused kernels / operations | Fused region | Unfused summed GPU time (us) | Fused GPU time (us) |','|---|---|---:|---:|']
groups=[('mHC WMMA projection → split reduction + input RMS/scale/bias → Sinkhorn → stream mixing → weighted RMSNorm','mHC input','mhc'),('Input quant → QA/KV WMMA → split-K reduce → RMSNorm → latent quant → QB WMMA → Q RMSNorm → Q RoPE + KV RoPE','QKV','qkv'),('Cache store → split-KV attention partials → attention reduce','Attention + reduce','attn')]
for ops,name,key in groups:lines.append(f"| {ops} | {name} | {gr[key+'_split']['median_us']:.3f} | {gr[key+'_fused']['median_us']:.3f} |")
lines += ['| Inverse RoPE → quant → OA → quant → OB | Attention output projections — next | Not rerun | Not rerun |','| mHC post → mHC projection → Sinkhorn → stream mixing → RMSNorm | Attention residual + FFN input | Not rerun | Not rerun |','| Router + shared expert + routed experts | MoE | Not rerun | Not rerun |','| Expert sum + shared add → mHC post | Final residual | Not rerun | Not rerun |','','Input quant now belongs to the QKV row; the earlier table counted it in mHC. Prior remaining-group measurements are preserved in ../full-layer-c1/regions/REPORT.md and ../full-layer-c1/all-wmma/REPORT.md, with their original vector controls and arithmetic limitations. They are not comparable fresh WMMA/TDM measurements. The next pipeline group is attention output projections; within the measured prefix, mHC is an important optimization target.','','## Validation and resources','','- 64 cases: nine checkpoint embedding inputs and 23 synthetic residual inputs at each of 128 and 1024 tokens. Fused and three-region intermediates/output match the stage-separated control within the unchanged 0.001 relative RMS gate.','- 9,216 changing-input graph invocations with deliberately stale current-token cache rows pass; maximum output discrepancy from split control is zero.','- Independent FP64 mHC projection reference maximum relative RMS: '+str(max(x['mhc_projection_reference_error'] for x in validation))+'.','- Independent FP64 attention reference maximum relative RMS: '+str(max(x['attention_reference_error'] for x in validation))+'.','- Numerical equivalence to this control does not establish full-layer native ATOM equivalence. The prior all-WMMA full-layer downstream rounding issue is not resolved by this experiment.','- Trace confirms 17 / 3 / 1 launches. Fully fused ASM retains TDM, WMMA, and L2 prefetch.','- Fully fused resource metadata: '+json.dumps(res)+'.','','## Reproduction','','Run `bash run.sh` inside the supplied gfx1250 container with this directory mounted as /work/mhc-through-attention, after checking GPU0 is idle. Standalone fixtures, code, skills, upstream MIT source/license, raw first/second-round samples, traces, assembly, LLVM, and checksums are included. No server, image, git branch, or serving script was changed.']
(p/'REPORT.md').write_text('\n'.join(lines)+'\n')
isa={}
for t in [128,1024]:
 s=(p/f't{t}_fused.amdgcn').read_text();isa[str(t)]={k:(v in s) for k,v in [('tdm','tensor_load_to_lds'),('wmma','v_wmma'),('l2_prefetch','global_prefetch_b8')]};assert all(isa[str(t)].values())
(p/'isa-verification.json').write_text(json.dumps(isa,indent=2))
(p/'STATUS.json').write_text(json.dumps(dict(complete=True,scope='Flash C1 mHC through attention reduction',splits=4,native_serving=False,validation_cases=len(validation),stress=stress,reported_round=2),indent=2))
print('\n'.join(lines))
